-- V6: Import data from quota.xlsx
-- Quotas, Designations, Departments, Fees from actual college data

-- semester_fee column is added by Hibernate hbm2ddl.auto=update after Flyway runs

-- Disable FK checks to allow parent table deletes
SET FOREIGN_KEY_CHECKS = 0;

-- Widen percentage column (decimal 5,2 -> 10,2) for values like 35000
ALTER TABLE admin_quota_master MODIFY percentage DECIMAL(10,2);

-- ============================
-- QUOTAS (from Sheet1)
-- ============================
DELETE FROM admin_quota_master;
ALTER TABLE admin_quota_master AUTO_INCREMENT = 1;


-- ============================
-- DESIGNATIONS (from Sheet2)
-- ============================
DELETE FROM admin_designation_master;
ALTER TABLE admin_designation_master AUTO_INCREMENT = 1;


-- ============================
-- DEPARTMENTS (from Sheet3)
-- ============================
DELETE FROM admin_department_master;
ALTER TABLE admin_department_master AUTO_INCREMENT = 1;


-- ============================
-- FEES (from Sheet4)
-- semester_fee column added by Hibernate hbm2ddl.auto=update
-- ============================
DELETE FROM admin_fees_master;
ALTER TABLE admin_fees_master AUTO_INCREMENT = 1;


-- Re-enable FK checks
SET FOREIGN_KEY_CHECKS = 1;